package com.yeyamo_mobile.api.culture_service.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="language_attempts") public class LanguageAttempt{@Id private UUID id;@Column(name="user_id",nullable=false)private String userId;@Column(name="lesson_id",nullable=false)private UUID lessonId;@Column(name="exercise_id",nullable=false)private UUID exerciseId;@Column(name="answer_text",columnDefinition="TEXT")private String answerText;@Column(name="media_id")private UUID mediaId;@Column(name="is_correct")private Boolean correct;@Column(name="feedback",columnDefinition="TEXT")private String feedback;@Column(name="created_at",nullable=false)private Instant createdAt;protected LanguageAttempt(){}public static LanguageAttempt create(String user,UUID lesson,UUID exercise,String answer,UUID media,Boolean correct){LanguageAttempt a=new LanguageAttempt();a.id=UUID.randomUUID();a.userId=user;a.lessonId=lesson;a.exerciseId=exercise;a.answerText=answer;a.mediaId=media;a.correct=correct;a.createdAt=Instant.now();return a;}public UUID getId(){return id;}public Boolean getCorrect(){return correct;}public UUID getMediaId(){return mediaId;}}
